		"agent.anthropic": false,
		"claude-code":     false,
		"codex":           false,
		"gemini":          false,
	}
	hasOpenRouter := false
	hasLocalQwen := false

	for _, entry := range models {
		if entry.OpenRouterID != "" {
			hasOpenRouter = true
		}
		if entry.DeploymentClass == deploymentClassLocalFree && entry.Family == "qwen" {
