// Package core contains the internal agent loop and provider-facing DTOs.
package core

import (
	"context"
	"encoding/json"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/reasoning"
	"github.com/DocumentDrivenDX/fizeau/telemetry"
)

// Status represents the outcome of a internal agent loop.
type Status string

const (
	StatusSuccess        Status = "success"
	StatusIterationLimit Status = "iteration_limit"
	StatusCancelled      Status = "cancelled"
	StatusError          Status = "error"
)

// Role identifies the sender of a message in the internal conversation history.
type Role string

const (
	RoleSystem    Role = "system"
	RoleUser      Role = "user"
	RoleAssistant Role = "assistant"
	RoleTool      Role = "tool"
)

// TokenUsage tracks input and output token counts for the internal loop API.
type TokenUsage struct {
	Input      int `json:"input"`
	Output     int `json:"output"`
	CacheRead  int `json:"cache_read,omitempty"`
	CacheWrite int `json:"cache_write,omitempty"`
	Total      int `json:"total"`
}

// Add accumulates token counts from another TokenUsage.
func (u *TokenUsage) Add(other TokenUsage) {
	u.Input += other.Input
	u.Output += other.Output
	u.CacheRead += other.CacheRead
	u.CacheWrite += other.CacheWrite
	u.Total += other.Total
}

// ToolCall represents a tool invocation requested by the model in the internal
// loop API.
type ToolCall struct {
	ID        string          `json:"id"`
	Name      string          `json:"name"`
	Arguments json.RawMessage `json:"arguments"`
}

// Message is a single message in the internal conversation history.
type Message struct {
	Role       Role       `json:"role"`
	Content    string     `json:"content,omitempty"`
	ToolCalls  []ToolCall `json:"tool_calls,omitempty"`
	ToolCallID string     `json:"tool_call_id,omitempty"`
}

// ToolDef describes a tool for the internal LLM provider interface.
type ToolDef struct {
	Name        string          `json:"name"`
	Description string          `json:"description"`
	Parameters  json.RawMessage `json:"parameters"` // JSON Schema
}

type Reasoning = reasoning.Reasoning

const (
	ReasoningAuto    = reasoning.ReasoningAuto
	ReasoningOff     = reasoning.ReasoningOff
	ReasoningLow     = reasoning.ReasoningLow
	ReasoningMedium  = reasoning.ReasoningMedium
	ReasoningHigh    = reasoning.ReasoningHigh
	ReasoningMinimal = reasoning.ReasoningMinimal
	ReasoningXHigh   = reasoning.ReasoningXHigh
	ReasoningMax     = reasoning.ReasoningMax
)

func ReasoningTokens(n int) Reasoning {
	return reasoning.ReasoningTokens(n)
}

// Options configures a single internal provider Chat call.
//
// SeamOptions is embedded to carry test injection seams when the testseam
// build tag is set; in production builds it is an empty struct with no fields.
type Options struct {
	SeamOptions

	Model       string   `json:"model,omitempty"`
	Temperature *float64 `json:"temperature,omitempty"`
	TopP        *float64 `json:"top_p,omitempty"`
	TopK        *int     `json:"top_k,omitempty"`
	MinP        *float64 `json:"min_p,omitempty"`
	// RepetitionPenalty is the OpenAI-compat field name; openai-compat
	// servers (omlx, lmstudio, vLLM, OpenRouter) accept it as a top-level
	// extra. >1.0 discourages exact repeats; 1.05–1.1 is typical for Qwen.
	RepetitionPenalty *float64 `json:"repetition_penalty,omitempty"`
	Seed              int64    `json:"seed,omitempty"`
	MaxTokens         int      `json:"max_tokens,omitempty"`
	Stop              []string `json:"stop,omitempty"`
	// SamplingSource is a comma-separated record of which resolution layers
	// supplied non-nil sampler fields, e.g. "catalog" or
	// "catalog,provider_config". Used only for the llm.request telemetry
	// event; never sent on the provider wire. See ADR-007 §5.
	SamplingSource string `json:"sampling_source,omitempty"`
	// Reasoning controls model-side reasoning with one scalar value. Empty means
	// unset; use ReasoningOff or ReasoningTokens(0) for explicit off.
	Reasoning Reasoning `json:"reasoning,omitempty"`

	// CachePolicy is the public prompt-caching opt-out plumbed from
	// ServiceExecuteRequest. Valid values: "" / "default" / "off". Providers
	// that implement caching (currently Anthropic, via cache_control writes
	// in a follow-up bead) consult this field; providers without caching
	// ignore it.
	CachePolicy string `json:"cache_policy,omitempty"`
}

// Response is the result of a single internal provider Chat call.
type Response struct {
	Content      string           `json:"content"`
	ToolCalls    []ToolCall       `json:"tool_calls,omitempty"`
	Usage        TokenUsage       `json:"usage"`
	Model        string           `json:"model"`
	FinishReason string           `json:"finish_reason"`
	Attempt      *AttemptMetadata `json:"attempt,omitempty"`
}

// Provider is the internal interface that LLM backends implement.
type Provider interface {
	Chat(ctx context.Context, messages []Message, tools []ToolDef, opts Options) (Response, error)
}

// Tool is the internal interface that agent tools implement.
type Tool interface {
	// Name returns the tool's identifier.
	Name() string
	// Description returns a human-readable description for the LLM.
	Description() string
	// Schema returns the JSON Schema for the tool's parameters.
	Schema() json.RawMessage
	// Execute runs the tool with the given parameters and returns the result.
	Execute(ctx context.Context, params json.RawMessage) (string, error)
	// Parallel reports whether this tool is safe to execute concurrently with
	// other parallel-flagged tools. Read-only tools return true; tools with
	// side effects (writes, shell commands, sub-agents) return false.
	Parallel() bool
}

// ToolCallLog records one tool execution during a internal agent loop.
type ToolCallLog struct {
	Tool     string          `json:"tool"`
	Input    json.RawMessage `json:"input"`
	Output   string          `json:"output"`
	Duration time.Duration   `json:"duration_ms"`
	Error    string          `json:"error,omitempty"`
}

// EventType identifies the kind of event emitted during a internal agent loop.
//
// uses ServiceEvent.
type EventType string

const (
	EventSessionStart    EventType = "session.start"
	EventLLMRequest      EventType = "llm.request"
	EventLLMResponse     EventType = "llm.response"
	EventToolCall        EventType = "tool.call"
	EventSessionEnd      EventType = "session.end"
	EventLLMDelta        EventType = "llm.delta"
	EventCompactionStart EventType = "compaction.start"
	EventCompactionEnd   EventType = "compaction.end"
	// EventOverride and EventRejectedOverride mirror the service-stream
	// override / rejected_override events into the session log so windowed
	// reporting (UsageReport, ADR-006 §5) can rebuild routing-quality
	// metrics across restarts and beyond the in-memory ring's retention.
	EventOverride         EventType = "override"
	EventRejectedOverride EventType = "rejected_override"
	// EventReasoningStall fires immediately before consumeStream returns
	// ErrReasoningStall. Its data payload carries model, timeout_ms,
	// reasoning_tail, and prompt_id so harnesses and dashboards can count
	// stall rate and debug what the model was reasoning about at the time.
	EventReasoningStall EventType = "reasoning.stall"
	// EventPlanningTurn fires after the planning LLM call completes when
	// Request.PlanningMode is enabled. Data: "plan" (string), "usage"
	// (TokenUsage), "model" (string).
	EventPlanningTurn EventType = "planning.turn"
)

// Event is a structured event emitted during a internal agent loop.
//
// uses ServiceEvent.
type Event struct {
	SessionID string          `json:"session_id"`
	Seq       int             `json:"seq"`
	Type      EventType       `json:"type"`
	Timestamp time.Time       `json:"ts"`
	Data      json.RawMessage `json:"data"`
}

// EventCallback receives events during a internal agent loop.
//
// returns a channel of ServiceEvent values.
type EventCallback func(Event)

// CostSource identifies where the recorded cost originated in the internal loop.
type CostSource string

const (
	CostSourceProviderReported CostSource = "provider_reported"
	CostSourceGatewayReported  CostSource = "gateway_reported"
	CostSourceConfigured       CostSource = "configured"
	CostSourceUnknown          CostSource = "unknown"
)

// CostAttribution captures the provenance of the cost associated with one
// internal provider attempt.
type CostAttribution struct {
	Source           CostSource      `json:"source,omitempty"`
	Currency         string          `json:"currency,omitempty"`
	Amount           *float64        `json:"amount,omitempty"`
	InputAmount      *float64        `json:"input_amount,omitempty"`
	OutputAmount     *float64        `json:"output_amount,omitempty"`
	CacheReadAmount  *float64        `json:"cache_read_amount,omitempty"`
	CacheWriteAmount *float64        `json:"cache_write_amount,omitempty"`
	ReasoningAmount  *float64        `json:"reasoning_amount,omitempty"`
	PricingRef       string          `json:"pricing_ref,omitempty"`
	Raw              json.RawMessage `json:"raw,omitempty"`
}

// TimingBreakdown captures optional provider timing windows for one internal
// attempt.
type TimingBreakdown struct {
	FirstToken *time.Duration `json:"first_token,omitempty"`
	Queue      *time.Duration `json:"queue,omitempty"`
	Prefill    *time.Duration `json:"prefill,omitempty"`
	Generation *time.Duration `json:"generation,omitempty"`
	CacheRead  *time.Duration `json:"cache_read,omitempty"`
	CacheWrite *time.Duration `json:"cache_write,omitempty"`
}

// AttemptMetadata captures the structured identity and attribution data for a
// single internal provider attempt.
//
// identity is reported through routing_decision and final ServiceEvent data.
type AttemptMetadata struct {
	AttemptIndex   int              `json:"attempt_index,omitempty"`
	ProviderName   string           `json:"provider_name,omitempty"`
	ProviderSystem string           `json:"provider_system,omitempty"`
	Route          string           `json:"route,omitempty"`
	ServerAddress  string           `json:"server_address,omitempty"`
	ServerPort     int              `json:"server_port,omitempty"`

package fizeau

import (
	"context"
	"fmt"
	"io"
	"path/filepath"
	"sync"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/harnesses"
	claudeharness "github.com/DocumentDrivenDX/fizeau/internal/harnesses/claude"
	codexharness "github.com/DocumentDrivenDX/fizeau/internal/harnesses/codex"
	geminiharness "github.com/DocumentDrivenDX/fizeau/internal/harnesses/gemini"
	"github.com/DocumentDrivenDX/fizeau/internal/routehealth"
	"github.com/DocumentDrivenDX/fizeau/internal/serviceimpl"
	sessionusage "github.com/DocumentDrivenDX/fizeau/internal/session"
)

// FizeauService is the entire public Go surface of the fizeau module.
// See CONTRACT-003 for the full specification.
type FizeauService interface {
	Execute(ctx context.Context, req ServiceExecuteRequest) (<-chan ServiceEvent, error)
	TailSessionLog(ctx context.Context, sessionID string) (<-chan ServiceEvent, error)
	ListHarnesses(ctx context.Context) ([]HarnessInfo, error)
	ListProviders(ctx context.Context) ([]ProviderInfo, error)
	ListModels(ctx context.Context, filter ModelFilter) ([]ModelInfo, error)
	ListProfiles(ctx context.Context) ([]ProfileInfo, error)
	ResolveProfile(ctx context.Context, name string) (*ResolvedProfile, error)
	ProfileAliases(ctx context.Context) (map[string]string, error)
	HealthCheck(ctx context.Context, target HealthTarget) error
	ResolveRoute(ctx context.Context, req RouteRequest) (*RouteDecision, error)
	RecordRouteAttempt(ctx context.Context, attempt RouteAttempt) error
	RouteStatus(ctx context.Context) (*RouteStatusReport, error)

	// Historical session-log projections. CONTRACT-003 owns these so CLI
	// subcommands such as log/replay/usage do not need to read the
	// internal session-log JSONL schema.
	UsageReport(ctx context.Context, opts UsageReportOptions) (*UsageReport, error)
	ListSessionLogs(ctx context.Context) ([]SessionLogEntry, error)
	WriteSessionLog(ctx context.Context, sessionID string, w io.Writer) error
	ReplaySession(ctx context.Context, sessionID string, w io.Writer) error
}

// ServiceConfig provides provider and routing data to the service without
// creating an import cycle from the root package into agent/config.
// Callers wrap their loaded *config.Config in a type that satisfies this interface.
type ServiceConfig interface {
	// ProviderNames returns provider names in stable order (default first).
	ProviderNames() []string
	// DefaultProviderName returns the name of the configured default provider.
	DefaultProviderName() string
	// Provider returns the raw config values for a named provider.
	Provider(name string) (ServiceProviderEntry, bool)
	// HealthCooldown returns the configured cooldown duration (0 = use default 30s).
	HealthCooldown() time.Duration
	// WorkDir is the base directory for file-backed health state.
	WorkDir() string
	// SessionLogDir returns the configured sessions directory.
	SessionLogDir() string
}

// ServiceProviderEntry carries the minimal provider data the service needs.
type ServiceProviderEntry struct {
	Type           string // "openai" | "openrouter" | "lmstudio" | "llama-server" | "omlx" | "lucebox" | "vllm" | "rapid-mlx" | "ollama" | "anthropic"
	BaseURL        string
	ServerInstance string
	Endpoints      []ServiceProviderEndpoint
	APIKey         string
	Headers        map[string]string
	Model          string // configured default model (may be empty)
	// ContextWindow is the configured provider-side context override.
	ContextWindow int
	// ConfigError marks this provider entry invalid while allowing the rest of
	// the service config to load. Invalid providers are reported in status
	// surfaces and excluded from routing.
	ConfigError string
	// DailyTokenBudget is the operator-configured per-UTC-day token budget
	// (request + response) for this provider. Zero means no local burn-rate
	// prediction; the provider's own quota signal still applies.
	DailyTokenBudget int
}

// ServiceProviderEndpoint is one configured provider serving endpoint.
type ServiceProviderEndpoint struct {
	Name           string
	BaseURL        string
	ServerInstance string
}

// ServiceOptions configures a FizeauService instance.
//
// seamOptions is embedded so production builds (no testseam tag) get an
// empty struct — making it a compile-time error to set seam fields without
// the build tag. Test builds inherit the four CONTRACT-003 seams
// (FakeProvider, PromptAssertionHook, CompactionAssertionHook,
// ToolWiringHook) automatically.
type ServiceOptions struct {
	seamOptions

	ConfigPath string    // optional override; default $XDG_CONFIG_HOME/fizeau/config.yaml
	Logger     io.Writer // optional; agent writes structured session logs internally regardless

	// ServiceConfig, when non-nil, supplies provider and routing data for
	// ListProviders and HealthCheck. Pass a value wrapping the loaded config.
	// When nil, those methods return an error.
	ServiceConfig ServiceConfig

	// QuotaRefreshDebounce is the minimum interval between live quota probes for
	// a primary subscription harness. Zero uses the service default.
	QuotaRefreshDebounce time.Duration
	// QuotaRefreshStartupWait bounds startup waiting when the durable quota
	// cache is missing, stale, or incomplete. Zero uses the service default.
	QuotaRefreshStartupWait time.Duration
	// QuotaRefreshInterval enables periodic refresh for long-running server
	// processes. Zero disables the timer; cache refresh still happens on startup
	// and service activity.
	QuotaRefreshInterval time.Duration
	// QuotaRefreshContext optionally cancels the periodic server refresh worker.
	// When nil, the worker uses context.Background().
	QuotaRefreshContext context.Context

	// CatalogProbeTimeout bounds live /v1/models discovery during routing.
	// Zero uses the service default of 2s.
	CatalogProbeTimeout time.Duration
	// CatalogRefreshTimeout bounds stale-while-revalidate catalog refreshes.
	// Zero uses the service default of 30s.
	CatalogRefreshTimeout time.Duration

	// LocalCostUSDPer1kTokens is the operator-supplied electricity/operations
	// estimate for local endpoint providers under the embedded agent harness.
	// Zero means local endpoint cost is unknown.
	LocalCostUSDPer1kTokens float64
	// SubscriptionCostCurve optionally overrides the default subscription
	// effective-cost curve used by routing.
	SubscriptionCostCurve *SubscriptionCostCurve

	// SessionLogDir overrides the directory used by historical session-log
	// projections (UsageReport, ListSessionLogs, WriteSessionLog,
	// ReplaySession). Empty falls back to ServiceConfig.SessionLogDir().
	// Per-Execute requests still set their own
	// ServiceExecuteRequest.SessionLogDir.
	SessionLogDir string

	// StaleHarnessReaperGrace is the minimum age before a startup reaper may
	// terminate an owned subprocess record. Zero uses the default grace window.
	StaleHarnessReaperGrace time.Duration
}

// SubscriptionCostCurve tunes effective subscription cost by quota utilization.
// Thresholds are percentages used, and multipliers are applied to the
// equivalent pay-per-token catalog rate.
type SubscriptionCostCurve struct {
	FreeUntilPercent   int
	LowUntilPercent    int
	MediumUntilPercent int
	LowMultiplier      float64
	MediumMultiplier   float64
	HighMultiplier     float64
}

// QuotaState is a live quota snapshot for a harness. Nil means not applicable.
type QuotaState struct {
	Windows    []harnesses.QuotaWindow `json:"windows"`
	CapturedAt time.Time               `json:"captured_at"`
	Fresh      bool                    `json:"fresh"`
	Source     string                  `json:"source,omitempty"`
	Status     string                  `json:"status,omitempty"` // ok|stale|unavailable|unauthenticated|unknown
	LastError  *StatusError            `json:"last_error,omitempty"`
}

// StatusError describes the most recent normalized status error for a harness,
// provider, or endpoint.
type StatusError struct {
	Type      string    // unavailable|unauthenticated|error
	Detail    string    // human-readable detail, safe for diagnostics
	Source    string    // config path, endpoint, cache path, or probe name
	Timestamp time.Time // zero when the source did not include a timestamp
}

// AccountStatus describes authentication/account state without exposing
// provider-specific native files to consumers.
type AccountStatus struct {
	Authenticated   bool
	Unauthenticated bool
	Email           string
	PlanType        string
	OrgName         string
	Source          string
	CapturedAt      time.Time
	Fresh           bool
	Detail          string
}

// UsageWindow describes normalized usage attribution over a time window.
// Empty token/cost totals mean the service has no historical usage source yet.
type UsageWindow struct {
	Name                string
	Source              string
	CapturedAt          time.Time
	Fresh               bool
	InputTokens         int
	OutputTokens        int
	TotalTokens         int
	CacheReadTokens     int
	CacheWriteTokens    int
	ReasoningTokens     int
	CostUSD             float64
	KnownCostUSD        *float64
	UnknownCostSessions int
}

// EndpointStatus describes one configured provider endpoint probe.
type EndpointStatus struct {
	Name           string
	BaseURL        string
	ServerInstance string
	ProbeURL       string
	Status         string // connected|unreachable|unauthenticated|error|unknown
	Source         string

